 "content": "def transform(grid):
    n = len(grid)
    separator = next(i for i in range(n) if grid[0][i] != 0)
    chamber = separator
    step = chamber + 1
    starts = list(range(0, n, step))

    # The exceptional patterned chamber supplies the shape to replicate.
    shape = None
    for r0 in starts:
        for c0 in starts:
            cells = {
                (r - r0, c - c0)
                for r in range(r0, r0 + chamber)
                for c in range(c0, c0 + chamber)
                if grid[r][c] not in (0, 5)
            }
            # Color tiles have area 4; the distinct motif is larger.
            if len(cells) > 4:
                shape = cells
                break
        if shape is not None:
            break

    # Each horizontal band has a color tile in its leftmost chamber.
    colors = [
        next(
            grid[r][c]
            for r in range(r0, r0 + chamber)
            for c in range(chamber)
            if grid[r][c] not in (0, 5)
        )
        for r0 in starts
    ]

    out = [[5 if grid[r][c] == 5 else 0 for c in range(n)] for r in range(n)]
    for band, r0 in enumerate(starts):
        for c0 in starts:
            for dr, dc in shape:
                out[r0 + dr][c0 + dc] = colors[band]
    return out
